    5: ['Май холодный — по примѣтамъ, годъ хлебородный.', 'Дождь въ мае — по примѣтамъ, къ урожаю ржи.', 'Многіе дубовые желуди въ мае — по примѣтамъ, къ стуже.'],
    6: ['Дождь въ июнѣ — по примѣтамъ, къ грибамъ.', 'Роса обильна въ июнѣ — по примѣтамъ, къ доброму сѣну.', 'Жаркій июнь — по примѣтамъ, къ ранней стуже.'],
    7: ['Гроза въ июлѣ — по примѣтамъ, къ богатому урожаю.', 'Дождь въ июлѣ — по примѣтамъ, къ хорошимъ сѣнокосамъ.'],
    8: ['Паутина въ августѣ — по примѣтамъ, къ теплой осени.', 'Дождь на Успеніе — по примѣтамъ, къ сухой осени.'],
    9: ['Осенній иней — по примѣтамъ, къ сухой и солнечной погодѣ.', 'Гуси летятъ высоко — по примѣтамъ, къ большой водѣ и поздней зимѣ.', 'Листъ желтѣетъ рано — по примѣтамъ, къ холодной зимѣ.'],
    10: ['Дубъ уронилъ листъ — по примѣтамъ, къ строгой зимѣ.', 'Паутина по утрамъ — по примѣтамъ, къ теплу.', 'Много рябины — по примѣтамъ, къ дождливой осени.'],
    11: ['Снѣгъ въ ноябрѣ — по примѣтамъ, къ вѣсненнему половодью.', 'Туманы въ ноябрѣ — по примѣтамъ, къ оттѣпели.', 'Галки да синицы по двору — по примѣтамъ, къ снѣгопаду.'],
    12: ['Звѣзды ярко въ декабрѣ — по примѣтамъ, къ большой стуже.', 'Иней въ декабрѣ — по примѣтамъ, къ урожаю.', 'Облака высокіе — по примѣтамъ, къ вѣтру.']
