  function holidayNearest45() {
    var today = new Date();
    var base = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    for (var k = 0; k < 60; k++) {
      var dt = new Date(base.getFullYear(), base.getMonth(), base.getDate() + k);
      var nm = holBy(dt.getMonth() + 1, dt.getDate());
      if (nm) {
        noteHoliday(nm); if (k === 0) return 'Нынче праздник: ' + nm + ', ' + nmOr() + '. Спрашивайте, что за праздникъ — растолкую.';
        return 'Ближайший праздник — ' + nm + ': через ' + numWords(k) + ' ' + formOf(k, 'день', 'дня', 'дней') + ', ' + nmOr() + '. Даты у меня въ тетрадке.';
      }
    }
    return 'Въ календаре моемъ праздниковъ на два мѣсяца впередъ не значится, ' + nmOr() + '.';
  }
  /* №59.7: праздникъ по конкретной датѣ — парсим «число + мѣсяцъ» изъ депеши */
  function holidayOnDate57(q) {
    var s = String(q || '').toLowerCase().replace(/ё/g, 'е').replace(/ѣ/g, 'е').replace(/[ъь]/g, '');
    var MON = { 'январ': 1, 'феврал': 2, 'март': 3, 'апрел': 4, 'ма': 5, 'июн': 6, 'июл': 7, 'август': 8, 'сентябр': 9, 'октябр': 10, 'ноябр': 11, 'декабр': 12 };
    var MONNAME = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
    var m = /(?:^|[^а-я])(\d{1,2})\s+(?:числа\s+)?(январ|феврал|март|апрел|ма|июн|июл|август|сентябр|октябр|ноябр|декабр)/.exec(s);
    if (m) {
      var d = parseInt(m[1], 10), mn2 = MON[m[2]];
      if (d >= 1 && d <= 31 && mn2) {
        var nm2 = holBy(mn2, d);
        if (nm2) { noteHoliday(nm2); return 'На ' + d + '-е ' + MONNAME[mn2 - 1] + ' праздникъ: ' + nm2 + ', ' + nmOr() + '. Спрашивайте, что за праздникъ — растолкую.'; }
        return 'На ' + d + '-е ' + MONNAME[mn2 - 1] + ' въ календарѣ моемъ праздника не значится, ' + nmOr() + '. Спросите о другомъ днѣ — сверю по журналамъ.';
      }
    }
    return holidayNearest45();
  }
  /* 55: перечень праздниковъ мѣсяца — «какіе праздники въ ноябрѣ» */
  function holidaysOfMonth55(n) {
    /* №59.6: депеши капсомъ доезжаютъ — мѣсяцъ ищется по нормализованной строкѣ */
    n = String(n || '').toLowerCase().replace(/ё/g, 'е').replace(/ѣ/g, 'е');
    var MO55 = [['январ', 1], ['феврал', 2], ['март', 3], ['апрел', 4], ['ма[йея]', 5],
                ['июн', 6], ['июл', 7], ['август', 8], ['сентябр', 9], ['октябр', 10],
                ['ноябр', 11], ['декабр', 12]];
    var mnum = 0;
    for (var i = 0; i < MO55.length; i++) {
      if (new RegExp('(^|[^а-я])' + MO55[i][0]).test(n)) { mnum = MO55[i][1]; break; }
    }
    if (!mnum) return null;
    var list = [], k;
    for (k = 0; k < HOL1896.length; k++) if (HOL1896[k][0] === mnum) list.push(HOL1896[k]);
    var MNAME55 = { 1: 'январѣ', 2: 'февралѣ', 3: 'мартѣ', 4: 'апрелѣ', 5: 'маѣ', 6: 'іюнѣ',
                    7: 'іюлѣ', 8: 'августѣ', 9: 'сентябрѣ', 10: 'октябрѣ', 11: 'ноябрѣ', 12: 'декабрѣ' };
    if (!list.length)
      return fill('Въ ' + MNAME55[mnum] + ', ' + nmOr() + ', въ моемъ календарѣ праздниковъ не значится. Спросите о другомъ мѣсяцѣ — сверю по журналамъ.');
    var parts = [];
    for (k = 0; k < list.length; k++) parts.push(list[k][1] + '-го — ' + list[k][2]);
    try { window.ZAHAR_SESSION = window.ZAHAR_SESSION || { lastWord: null, lastField: null }; window.ZAHAR_SESSION.lastHolMonth = mnum; } catch (e56) {}
    var lead = (list.length === 1) ? 'значится праздникъ' : 'значатся праздники';
    return fill('Въ ' + MNAME55[mnum] + ', ' + nmOr() + ', у меня въ календарѣ ' + lead + ': ' + parts.join('; ') + '. О любомъ растолкую — назовите.');
  }
  /* ============================================================
     №54: ярусъ памяти разговора.
     Праздник назван — Захаръ помнитъ тему; «что это», «это что», «про него»,
     «расскажи еще» докладываютъ о ней. Прямыя вопросы по имени праздника
     работаютъ безъ оглядки на память. Темы тетради (zahar_custom.js)
     записываются черезъ window.__zaharNoteTopic — крючокъ в answerFrom.
     ============================================================ */
  var TOPIC_MEM = { key: null, name: '', variants: [], seen: -1, tick: 0 };
  function noteTopic(name, variants, shown, keep) {
    try {
      if (!name) return;
      var k = norm(String(name));
      if (!k) return;
      var vs = [];
      var arr = variants || [];
      for (var i = 0; i < arr.length; i++) {
        var t = String(arr[i] || '').trim();
        if (t && vs.indexOf(t) < 0) vs.push(t);
      }
      if (TOPIC_MEM.key === k) {
        for (var j = 0; j < vs.length; j++) if (TOPIC_MEM.variants.indexOf(vs[j]) < 0) TOPIC_MEM.variants.push(vs[j]);
        if (keep && shown >= 0) TOPIC_MEM.seen = Math.min(Math.max(shown, 0), Math.max(TOPIC_MEM.variants.length - 1, 0));
        else if (shown === 0) TOPIC_MEM.seen = -1;
        return;
      }
      TOPIC_MEM = { key: k, name: String(name), variants: vs, seen: (keep && shown >= 0) ? Math.min(Math.max(shown, 0), Math.max(vs.length - 1, 0)) : (shown === 0 ? -1 : Math.min(Math.max(shown || 0, 1), Math.max(vs.length - 1, 0))), tick: (window.__zaharTurn59e || 0) };
    } catch (eNT) { warn('noteTopic: ' + eNT); }
  }
  window.__zaharNoteTopic = noteTopic;

  /* №59.9я: Пасха по алгоритму — юлианская дата + 13 дней = наш счёт, без года */
  function zaharEasterTxt59() {
    var y = new Date().getFullYear();
    for (;;) {
      var a = y % 4, b = y % 7, c = y % 19;
      var d = (19 * c + 15) % 30, e = (2 * a + 4 * b - d + 34) % 7;
      var mm = Math.floor((d + e + 114) / 31), day = ((d + e + 114) % 31) + 1;
      var g = new Date(y, mm - 1, day + 13);
      if (g >= new Date())
        return g.getDate() + '-го ' + ['января','февраля','марта','апреля','мая','іюня','іюля','августа','сентября','октября','ноября','декабря'][g.getMonth()];
      y++;
    }
  }
