  /* №59.9ш: детектор зверя — послѣдняя «на …» безъ «не» побѣждаетъ */
  function zaharHuntAnimal59(raw) {
    var s = String(raw || '').toLowerCase().replace(/ё/g, 'е');
    var RE = [['зайц[а-я]*','заяц'],['лос[а-я]*','лось'],['медвед[а-я]*','медвѣдь'],['медвѣд[а-я]*','медвѣдь'],
      ['утк[а-я]*','утка'],['глухар[а-я]*','глухарь'],['тетерев[а-я]*','тетерев'],['рябчик[а-я]*','рябчик'],
      ['белк[а-я]*','белка'],['косул[а-я]*','косуля'],['кабарг[а-я]*','кабарга'],['кабан[а-я]*','кабан'],
      ['лис[уаы]','лиса'],['рыс[ьи]','рысь'],['волк[а-я]*','волк'],['собол[а-я]*','соболь'],['барсук[а-я]*','барсук']];
    var hits = [], re = /(^|[^а-я])на\s+([а-яѣ]+)/g, m;
    while ((m = re.exec(s))) {
      var w = m[2];
      for (var k = 0; k < RE.length; k++) {
        if (new RegExp('^(' + RE[k][0] + ')$').test(w)) {
          hits.push({ a: RE[k][1], neg: /не\s+(на\s+)?$/.test(s.slice(0, m.index)) || /не\s+$/.test(s.slice(Math.max(0, m.index - 12), m.index)) });
          break;
        }
      }
    }
    if (!hits.length) return null;
    var good = [];
    for (var g = 0; g < hits.length; g++) if (!hits[g].neg) good.push(hits[g]);
    var chosen = good.length ? good[good.length - 1] : hits[hits.length - 1];
    return chosen.a;
  }

